-- Economics G2 T6 content upgrade: append-only question versions; transaction aborts on any violation.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='90s';
DO $t$
DECLARE
 d jsonb:='[{"ref":"EC9708:G2:EC9708-G2-T6-P-011","d":"hard","sec":190,"k":"C","en":"An economy follows the simplified expectations-augmented Phillips curve π=πe−(u−5), where π is inflation (%), πe expected inflation (%) and u unemployment (%). Actual unemployment remains at 3%. Expected inflation is 4% in year one and adjusts to 6% in year two. What is actual inflation in the two years, assuming the equation otherwise stays unchanged?","ru":"В экономике используется упрощённая кривая Филлипса с ожиданиями: π=πe−(u−5), где π — инфляция (%), πe — ожидаемая инфляция (%), u — безработица (%). Фактическая безработица остаётся 3%. Ожидания инфляции равны 4% в первом году и повышаются до 6% во втором. Какова фактическая инфляция в оба года?","uz":"Iqtisodiyotda kutishlarni hisobga olgan soddalashtirilgan Fillips egri chizig‘i π=πe−(u−5), bunda π inflyatsiya (%), πe kutilgan inflyatsiya (%), u ishsizlik (%). Ishsizlik 3% bo‘lib qoladi. Kutilgan inflyatsiya birinchi yili 4%, ikkinchi yili 6%. Boshqa shart o‘zgarmasa, haqiqiy inflyatsiya nechaga teng?","options_en":["Year 1: 4%; year 2: 6%","Year 1: 2%; year 2: 4%","Year 1: 6%; year 2: 8%","Year 1: 6%; year 2: 6%"],"options_ru":["1-й год: 4%; 2-й: 6%","1-й год: 2%; 2-й: 4%","1-й год: 6%; 2-й: 8%","1-й год: 6%; 2-й: 6%"],"options_uz":["1-yil: 4%; 2-yil: 6%","1-yil: 2%; 2-yil: 4%","1-yil: 6%; 2-yil: 8%","1-yil: 6%; 2-yil: 6%"],"why":["When u=3, −(u−5)=+2. Thus inflation is 4+2=6% initially and 6+2=8% after expectations rise. Sustaining unemployment below the natural rate can raise inflation.","При u=3 добавка к инфляции равна +2. Поэтому сначала 4+2=6%, затем 6+2=8%. Сохранение безработицы ниже естественной может ускорять инфляцию.","u=3 bo‘lsa, inflyatsiyaga qo‘shimcha +2. Avval 4+2=6%, keyin 6+2=8%. Ishsizlik tabiiy darajadan past bo‘lsa, inflyatsiya tezlashishi mumkin."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-030","d":"hard","sec":195,"k":"B","en":"An economy has spare capacity and a fixed price level. The sum of marginal leakages from saving, tax and imports is 0.40 per extra dollar of income. Government purchases rise by $40m, but private investment simultaneously falls by $12m. Treat both as autonomous spending changes. What is the predicted total change in equilibrium income?","ru":"В экономике есть свободные мощности и фиксированный уровень цен. Сумма предельных изъятий на сбережения, налоги и импорт равна 0,40 на дополнительный доллар дохода. Госзакупки растут на $40 млн, но частные инвестиции одновременно падают на $12 млн. Оба изменения автономны. Как изменится равновесный доход?","uz":"Iqtisodiyotda bo‘sh quvvat va o‘zgarmas narx bor. Qo‘shimcha daromaddan jamg‘arma, soliq va importga chegaraviy chiqimlar yig‘indisi 0,40. Davlat xaridi $40 mln oshadi, xususiy investitsiya esa $12 mln kamayadi. Ikkisi ham avtonom o‘zgarish. Muvozanat daromadi qancha o‘zgaradi?","options_en":["+ $100m","+ $70m","+ $28m","− $70m"],"options_ru":["+ $100 млн","+ $70 млн","+ $28 млн","− $70 млн"],"options_uz":["+ $100 mln","+ $70 mln","+ $28 mln","− $70 mln"],"why":["Multiplier=1/0.40=2.5. Net autonomous injection=40−12=$28m. Therefore ΔY=2.5×28=$70m, not $100m.","Мультипликатор 1/0,40=2,5. Чистый автономный импульс 40−12=$28 млн; прирост дохода 2,5×28=$70 млн.","Multiplikator 1/0,40=2,5. Sof avtonom qo‘shimcha 40−12=$28 mln; daromad o‘sishi 2,5×28=$70 mln."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-034","d":"hard","sec":195,"k":"D","en":"Five equally sized income groups receive $10m, $15m, $20m, $25m and $30m before growth. After growth, their incomes are $9m, $16m, $22m, $28m and $37m. What happens to total real income and the poorest group''s share of the total?","ru":"Пять одинаковых по численности групп первоначально получают $10, $15, $20, $25 и $30 млн дохода. После роста экономики — $9, $16, $22, $28 и $37 млн. Что происходит с общим реальным доходом и долей беднейшей группы?","uz":"Aholisi teng besh daromad guruhining dastlabki daromadlari $10, $15, $20, $25 va $30 mln. O‘sishdan keyin $9, $16, $22, $28 va $37 mln. Jami real daromad va eng kambag‘al guruh ulushi qanday o‘zgaradi?","options_en":["Total rises 10%; poorest share stays 10%","Total rises 12%; poorest income increases 12%","Total falls 12%; poorest share rises to 12%","Total rises 12%; poorest share falls from 10% to about 8.0%"],"options_ru":["Общий доход +10%; доля беднейших остаётся 10%","Общий доход +12%; доход беднейших также +12%","Общий доход −12%; доля беднейших растёт до 12%","Общий доход +12%; доля беднейших падает с 10% примерно до 8,0%"],"options_uz":["Jami daromad +10%; kambag‘allar ulushi 10% qoladi","Jami daromad +12%; kambag‘allar daromadi ham +12%","Jami daromad −12%; kambag‘allar ulushi 12% ga oshadi","Jami daromad +12%; eng kambag‘al ulushi 10% dan taxminan 8,0% ga tushadi"],"why":["Total increases from $100m to $112m (+12%). The poorest group falls from $10m to $9m and its share from 10/100=10% to 9/112≈8.0%; growth is not evenly shared.","Общий доход растёт со $100 до $112 млн (+12%). Доход беднейших падает с $10 до $9 млн, доля с 10% до 9/112≈8,0%.","Jami daromad $100 mln dan $112 mln ga (+12%) oshadi. Eng kambag‘al guruh $10 mln dan $9 mln ga tushadi, ulushi 10% dan 9/112≈8,0% ga kamayadi."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-038","d":"hard","sec":180,"k":"C","en":"An economy initially runs a current-account deficit of $30m. Following a boom, national income increases by $80m and the marginal propensity to import is 0.20. At the same time, exports rise independently by $5m. Assume other current-account entries remain fixed. What is the new current-account balance?","ru":"Изначально дефицит текущего счёта экономики $30 млн. Во время подъёма национальный доход увеличивается на $80 млн при MPM=0,20. Одновременно экспорт независимо растёт на $5 млн. Остальные статьи текущего счёта неизменны. Каково новое сальдо?","uz":"Iqtisodiyotning dastlabki joriy hisob taqchilligi $30 mln. O‘sish davrida milliy daromad $80 mln oshadi, importga chegaraviy moyillik MPM=0,20. Shu paytda eksport mustaqil $5 mln ko‘payadi. Boshqa joriy hisob bandlari o‘zgarmaydi. Yangi balans qancha?","options_en":["−$9m","−$16m","−$41m","−$51m"],"options_ru":["−$9 млн","−$16 млн","−$41 млн","−$51 млн"],"options_uz":["−$9 mln","−$16 mln","−$41 mln","−$51 mln"],"why":["Imports increase by 0.20×$80m=$16m while exports increase $5m; the balance worsens $11m from −$30m to −$41m.","Импорт растёт на 0,20×$80 млн=$16 млн, экспорт на $5 млн. Сальдо ухудшается на $11 млн: с −$30 млн до −$41 млн.","Import 0,20×$80 mln=$16 mln, eksport $5 mln oshadi. Balans $11 mln yomonlashib −$30 mln dan −$41 mln ga o‘tadi."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-039","d":"hard","sec":180,"k":"A","en":"Fifty unemployed workers have matching skills for jobs in another region. Each relocation creates $8,000 of additional real output in the first year but uses $3,000 in real moving and housing resources. The government pays each worker a $2,000 grant, financed by lump-sum tax, without administrative or tax-distortion costs. What is the first-year NET social resource gain from all 50 moves?","ru":"Пятьдесят безработных имеют навыки для вакансий в другом регионе. Каждый переезд создаёт в первый год дополнительно $8 000 реального выпуска, но требует $3 000 реальных ресурсов на переезд и жильё. Государство выдаёт каждому грант $2 000, финансируемый паушальным налогом, без затрат администрирования и налоговых искажений. Каков чистый ресурсный выигрыш общества за первый год от всех переездов?","uz":"50 ishsizning malakasi boshqa hududdagi ishga mos. Har bir ko‘chish birinchi yilda $8000 qo‘shimcha real mahsulot yaratadi, lekin ko‘chish va uy-joyga $3000 real resurs ketadi. Davlat har biriga $2000 grant beradi, u bir martalik soliq bilan moliyalanadi, boshqaruv va soliq buzilishi yo‘q. Barcha 50 ko‘chishning birinchi yildagi sof ijtimoiy resurs foydasi qancha?","options_en":["$250,000","$150,000","$400,000","$100,000"],"options_ru":["$250 000","$150 000","$400 000","$100 000"],"options_uz":["$250 000","$150 000","$400 000","$100 000"],"why":["Net additional output after real resource costs is ($8,000−$3,000)×50=$250,000. The $2,000 grants are transfers between taxpayers and workers, not additional real resource consumption under the assumptions.","Чистая выгода ($8 000−$3 000)×50=$250 000. Гранты — перераспределение между налогоплательщиками и работниками, не дополнительный расход реальных ресурсов при данных допущениях.","Sof foyda ($8000−$3000)×50=$250 000. Grantlar soliq to‘lovchi va ishchi o‘rtasidagi transfert bo‘lib, berilgan shartlarda qo‘shimcha real resurs sarfi emas."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-042","d":"hard","sec":195,"k":"B","en":"In a loanable-funds market, saving supply is S=20+3r and private investment demand is I=100−5r, where r is the interest rate in percentage points. Government borrowing of 20 units adds to demand for funds without directly changing private investment demand. What are the new equilibrium interest rate and reduction in private investment?","ru":"На рынке заёмных средств предложение сбережений S=20+3r, частный инвестиционный спрос I=100−5r, где r — ставка в процентных пунктах. Госзаимствования на 20 единиц увеличивают общий спрос на средства, не сдвигая функцию частных инвестиций. Найдите новую равновесную ставку и сокращение частных инвестиций.","uz":"Qarz mablag‘lari bozorida jamg‘arma taklifi S=20+3r, xususiy investitsiya talabi I=100−5r, r foiz punktdagi stavka. Davlatning 20 birlik qarzi mablag‘ga umumiy talabni oshiradi, xususiy investitsiya funksiyasini siljitmaydi. Yangi muvozanat stavkasi va xususiy investitsiyaning kamayishi qancha?","options_en":["r=10%; private investment falls by 20","r=12.5%; private investment falls by 12.5","r=15%; private investment rises by 20","r=12.5%; private investment is unchanged"],"options_ru":["r=10%; частные инвестиции падают на 20","r=12,5%; частные инвестиции сокращаются на 12,5","r=15%; частные инвестиции растут на 20","r=12,5%; частные инвестиции неизменны"],"options_uz":["r=10%; xususiy investitsiya 20 ga kamayadi","r=12,5%; xususiy investitsiya 12,5 ga kamayadi","r=15%; xususiy investitsiya 20 ga oshadi","r=12,5%; xususiy investitsiya o‘zgarmaydi"],"why":["Initially 20+3r=100−5r, giving r=10 and private I=50. New demand I+20 gives 20+3r=120−5r, r=12.5, private I=37.5. Crowding out=12.5.","Сначала r=10 и частные инвестиции 50. После госзаимствований r=12,5, частные инвестиции 37,5. Вытеснение 50−37,5=12,5.","Dastlab r=10, xususiy I=50. Davlat qarzidan keyin r=12,5, xususiy I=37,5. Siqib chiqarish 12,5."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-044","d":"hard","sec":185,"k":"D","en":"A central bank buys $200m of foreign currency from domestic banks and pays by creating domestic reserves. It then sells $150m of domestic government securities to those banks, which pay from their reserves. There are no other transactions. What is the net immediate effect on the domestic monetary base?","ru":"Центральный банк покупает у местных банков иностранную валюту на $200 млн, создавая резервы в национальной валюте. Затем продаёт тем же банкам государственные бумаги на $150 млн, которые те оплачивают из резервов. Других операций нет. Каково чистое немедленное изменение денежной базы?","uz":"Markaziy bank mahalliy banklardan $200 mln xorijiy valuta sotib olib, milliy valutada zaxira yaratadi. So‘ng ularga $150 mln mahalliy davlat obligatsiyasini sotadi, banklar zaxiradan to‘laydi. Boshqa operatsiya yo‘q. Pul bazasi darhol sof qancha o‘zgaradi?","options_en":["Decreases $350m","Increases $350m","Decreases $50m","Increases $50m"],"options_ru":["Снижается на $350 млн","Увеличивается на $350 млн","Снижается на $50 млн","Увеличивается на $50 млн"],"options_uz":["$350 mln kamayadi","$350 mln oshadi","$50 mln kamayadi","$50 mln oshadi"],"why":["The FX purchase adds $200m bank reserves; security sales withdraw $150m, leaving a $50m monetary-base increase. The second operation partially sterilises the first.","Покупка валюты добавляет $200 млн резервов, продажа бумаг изымает $150 млн. Чистый рост базы $50 млн: частичная стерилизация.","Valuta xaridi zaxirani $200 mln oshiradi, obligatsiya sotuvi $150 mln kamaytiradi. Sof pul bazasi +$50 mln: qisman sterilizatsiya."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-046","d":"hard","sec":175,"k":"A","en":"Transactions and speculative money demand in an economy follow the illustrative linear rule Md=0.3Y−20r, with Y measured in million dollars and r in percentage-point units. Income rises from 1,000 to 1,100 while the interest rate falls from 5 to 4. What is the combined change in money demanded?","ru":"Спрос на деньги задаётся иллюстративной функцией Md=0,3Y−20r, где Y — доход в млн долларов, r — процентная ставка в процентных пунктах. Доход растёт с 1 000 до 1 100, а ставка снижается с 5 до 4. На сколько в совокупности меняется спрос на деньги?","uz":"Pulga talabning misoliy funksiyasi Md=0,3Y−20r, bunda Y mln dollardagi daromad, r foiz punktlardagi stavka. Daromad 1000 dan 1100 ga oshadi, stavka 5 dan 4 ga tushadi. Pulga umumiy talab qancha o‘zgaradi?","options_en":["Increases by 50 million","Increases by 30 million","Decreases by 20 million","Remains unchanged"],"options_ru":["Увеличивается на 50 млн","Увеличивается на 30 млн","Уменьшается на 20 млн","Не изменяется"],"options_uz":["50 mln ga oshadi","30 mln ga oshadi","20 mln ga kamayadi","O‘zgarmaydi"],"why":["Initially Md=0.3×1000−20×5=200. Afterwards Md=0.3×1100−20×4=250, a rise of 50, reflecting both income and interest-rate effects.","Изначально Md=0,3×1000−20×5=200. Затем Md=0,3×1100−20×4=250. Рост на 50 вызван обеими переменными.","Dastlab Md=0,3×1000−20×5=200. Keyin Md=0,3×1100−20×4=250. Ikkala omil tufayli o‘sish 50."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-047","d":"hard","sec":195,"k":"B","en":"An economy''s labour force is 5 million. At the recession trough, 100,000 are frictionally unemployed, 150,000 structurally unemployed and 250,000 cyclically unemployed. Assuming none of these categories overlap and the labour force stays constant, what are its actual unemployment rate and its approximate natural unemployment rate after cyclical unemployment disappears?","ru":"Рабочая сила страны — 5 млн человек. В нижней точке рецессии 100 000 фрикционных, 150 000 структурных и 250 000 циклических безработных. Категории не пересекаются, численность рабочей силы постоянна. Каковы фактический уровень безработицы и примерный естественный уровень после исчезновения циклической безработицы?","uz":"Mamlakat ishchi kuchi 5 mln. Tanazzul tubida 100 000 friksion, 150 000 tarkibiy va 250 000 davriy ishsiz bor. Guruhlar kesishmaydi, ishchi kuchi o‘zgarmaydi. Haqiqiy ishsizlik darajasi va davriy ishsizlik yo‘qolgandan keyingi taxminiy tabiiy daraja qancha?","options_en":["Actual 5%; natural 10%","Actual 10%; natural 5%","Actual 10%; natural 0%","Actual 15%; natural 5%"],"options_ru":["Фактический 5%; естественный 10%","Фактический 10%; естественный 5%","Фактический 10%; естественный 0%","Фактический 15%; естественный 5%"],"options_uz":["Haqiqiy 5%; tabiiy 10%","Haqiqiy 10%; tabiiy 5%","Haqiqiy 10%; tabiiy 0%","Haqiqiy 15%; tabiiy 5%"],"why":["Actual unemployment=(100k+150k+250k)/5m=10%. Frictional plus structural unemployment=(100k+150k)/5m=5% natural-rate approximation.","Фактическая безработица (100+150+250) тыс./5 млн=10%; фрикционная и структурная (100+150) тыс./5 млн=5% естественного уровня.","Haqiqiy ishsizlik (100+150+250) ming/5 mln=10%; friksion va tarkibiy (100+150) ming/5 mln=5% tabiiy daraja."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-048","d":"hard","sec":185,"k":"C","en":"An accredited programme retrains 100 structurally unemployed workers for currently vacant technical roles. Each placed worker is expected to generate an extra $80,000 of real output in the first year, with no displaced output elsewhere. The one-time real resource cost of training is $1m. Ignore other effects. What is the first-year net resource gain and unemployment mechanism addressed?","ru":"Аккредитованная программа переучивает 100 структурно безработных для существующих технических вакансий. Каждый трудоустроенный создаст в первый год дополнительно $80 000 реального выпуска без вытеснения выпуска в других местах. Реальные разовые ресурсы на обучение стоят $1 млн. Прочие эффекты игнорируются. Каковы чистый ресурсный выигрыш за год и устраняемый механизм безработицы?","uz":"Akkreditatsiyalangan dastur 100 nafar tarkibiy ishsizni mavjud texnik vakansiyalar uchun qayta o‘qitadi. Ishga kirgan har biri birinchi yilda boshqa ishlab chiqarishni siqib chiqarmasdan $80 000 qo‘shimcha real mahsulot yaratadi. Bir martalik real o‘qitish xarajati $1 mln. Boshqa ta’sir yo‘q. Birinchi yil sof resurs foydasi va bartaraf etiladigan ishsizlik sababi qanday?","options_en":["$8m; purely cyclical unemployment","$1m; seasonal unemployment","$7m; skills mismatch causing structural unemployment","$7m; frictional unemployment caused solely by job-search delays"],"options_ru":["$8 млн; исключительно циклическая безработица","$1 млн; сезонная безработица","$7 млн; несоответствие квалификации и структурная безработица","$7 млн; только фрикционные задержки поиска работы"],"options_uz":["$8 mln; faqat davriy ishsizlik","$1 mln; mavsumiy ishsizlik","$7 mln; malaka mos kelmasligi sabab tarkibiy ishsizlik","$7 mln; faqat ish izlashning friksion kechikishi"],"why":["Extra output=100×$80,000=$8m, minus real training resources $1m gives $7m net first-year gain. Retraining tackles a mismatch of skills to vacancies.","Дополнительный выпуск 100×$80 000=$8 млн, минус ресурсы обучения $1 млн = $7 млн. Переобучение исправляет структурный разрыв навыков.","Qo‘shimcha mahsulot 100×$80 000=$8 mln, o‘qitish resursi $1 mln; sof $7 mln. Qayta o‘qitish vakansiya bilan malaka nomuvofiqligini kamaytiradi."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-052","d":"hard","sec":190,"k":"B","en":"The quantity-theory identity is MV=PT. Over one year, the money stock M rises by 10%, velocity V falls by 5%, and the real volume of transactions T rises by 3%. Applying the index ratios exactly, approximately how much does the implied price index P change?","ru":"В тождестве количественной теории MV=PT за год денежная масса M растёт на 10%, скорость обращения V снижается на 5%, реальный объём операций T растёт на 3%. Используя точное отношение индексов, примерно на сколько меняется индекс цен P?","uz":"MV=PT miqdoriy nazariyasi ayniyatida bir yilda pul massasi M 10% oshadi, aylanish tezligi V 5% kamayadi, real tranzaksiyalar T 3% oshadi. Indekslarning aniq nisbatidan foydalanib P narx indeksi taxminan qancha o‘zgaradi?","options_en":["+18.0%","+1.46%","+2.0%","−1.46%"],"options_ru":["+18,0%","+1,46%","+2,0%","−1,46%"],"options_uz":["+18,0%","+1,46%","+2,0%","−1,46%"],"why":["Price factor=(1.10×0.95)/1.03≈1.01456, so the implied price increase is around 1.46%. Simple addition of growth rates is only an approximation.","Коэффициент цен (1,10×0,95)/1,03≈1,01456, прирост около 1,46%. Простое сложение темпов даёт лишь приближение.","Narx koeffitsienti (1,10×0,95)/1,03≈1,01456, o‘sish taxminan 1,46%. Foizlarni oddiy qo‘shish faqat yaqinlashishdir."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-053","d":"hard","sec":195,"k":"D","en":"The labour force is 4.8 million. Initially 0.1m are frictionally unemployed, 0.2m structurally unemployed and 0.3m cyclically unemployed. Retraining moves 0.1m from structural unemployment directly into jobs, while recovery employs 0.2m cyclically unemployed people; no one leaves the labour force. What are the new actual and approximate natural unemployment rates?","ru":"Рабочая сила — 4,8 млн. Первоначально 0,1 млн фрикционных, 0,2 млн структурных и 0,3 млн циклических безработных. Переобучение трудоустраивает 0,1 млн из структурной группы, восстановление экономики — 0,2 млн циклических; рабочую силу никто не покидает. Каковы новые фактический и приблизительный естественный уровни безработицы?","uz":"Ishchi kuchi 4,8 mln. Dastlab 0,1 mln friksion, 0,2 mln tarkibiy va 0,3 mln davriy ishsiz bor. Qayta tayyorlash 0,1 mln tarkibiy ishsizni, tiklanish 0,2 mln davriy ishsizni ishga joylaydi; hech kim ishchi kuchidan chiqmaydi. Yangi haqiqiy va taxminiy tabiiy ishsizlik darajasi qanday?","options_en":["Actual 12.5%; natural 6.25%","Actual 4.17%; natural 6.25%","Actual 6.25%; natural 6.25%","Actual 6.25%; natural 4.17%"],"options_ru":["Фактический 12,5%; естественный 6,25%","Фактический 4,17%; естественный 6,25%","Фактический 6,25%; естественный 6,25%","Фактический 6,25%; естественный 4,17%"],"options_uz":["Haqiqiy 12,5%; tabiiy 6,25%","Haqiqiy 4,17%; tabiiy 6,25%","Haqiqiy 6,25%; tabiiy 6,25%","Haqiqiy 6,25%; tabiiy 4,17%"],"why":["Remaining unemployed: frictional 0.1m, structural 0.1m, cyclical 0.1m, total 0.3m. Actual=0.3/4.8=6.25%; natural≈(0.1+0.1)/4.8≈4.17%.","Остаётся по 0,1 млн в каждой категории, всего 0,3 млн. Фактическая 0,3/4,8=6,25%; естественная (0,1+0,1)/4,8≈4,17%.","Har uch toifada 0,1 mln qoladi, jami 0,3 mln. Haqiqiy 0,3/4,8=6,25%, tabiiy (0,1+0,1)/4,8≈4,17%."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-055","d":"hard","sec":185,"k":"C","en":"A central bank starts with $800m in usable foreign-exchange reserves. It sells $120m to buy its domestic currency in a floating market, with no offsetting operations. Monthly imports remain $100m and no other reserves change. How does its simple import-cover ratio change, and which limitation becomes more relevant?","ru":"Центральный банк имеет $800 млн доступных валютных резервов. Он продаёт $120 млн, выкупая национальную валюту на плавающем рынке, без компенсирующих операций. Месячный импорт остаётся $100 млн, других изменений резервов нет. Как меняется простое покрытие импорта резервами и какое ограничение усиливается?","uz":"Markaziy bankda $800 mln ishlatiladigan valuta zaxirasi bor. Suzuvchi bozorda milliy valutani sotib olish uchun $120 mln xorijiy valuta sotadi, boshqa operatsiya yo‘q. Oylik import $100 mln, zaxirada boshqa o‘zgarish yo‘q. Importni qoplash muddati qanday o‘zgaradi va qaysi cheklov kuchayadi?","options_en":["From 8 to 9.2 months; reserves expand","From 8 to 1.2 months; intervention has no limit","From 8 to 6.8 months; repeated defence can deplete usable reserves","From 8 to 6.8 months; import prices automatically fall"],"options_ru":["С 8 до 9,2 месяца; резервы растут","С 8 до 1,2 месяца; интервенции не ограничены","С 8 до 6,8 месяца; повторная защита курса может истощать резервы","С 8 до 6,8 месяца; импортные цены обязательно падают"],"options_uz":["8 oydan 9,2 oyga; zaxira kengayadi","8 oydan 1,2 oyga; aralashuv cheksiz","8 oydan 6,8 oyga; kursni takror himoya qilish zaxirani kamaytirishi mumkin","8 oydan 6,8 oyga; import narxlari albatta tushadi"],"why":["Reserves fall from $800m to $680m. Import cover declines from 800/100=8 months to 680/100=6.8 months, highlighting a finite-reserve constraint.","Резервы снижаются с $800 до $680 млн; покрытие с 800/100=8 до 680/100=6,8 месяца. Повторные интервенции ограничены запасом резервов.","Zaxira $800 mln dan $680 mln ga tushadi. Qoplash 800/100=8 oydan 680/100=6,8 oyga kamayadi. Intervensiya zaxira bilan cheklangan."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-056","d":"hard","sec":180,"k":"B","en":"A country reports 8% real GDP per-person growth, but a poverty-gap index rises from 0.20 to 0.30, and child malnutrition also rises. What percentage did the poverty-gap index increase, and which conclusion about development is defensible?","ru":"В стране реальный ВВП на человека вырос на 8%, но индекс глубины бедности повысился с 0,20 до 0,30, также выросло недоедание среди детей. На сколько процентов увеличился индекс глубины бедности и какой вывод о развитии обоснован?","uz":"Mamlakatda jon boshiga real YaIM 8% oshdi, ammo kambag‘allik tafovuti indeksi 0,20 dan 0,30 ga chiqdi va bolalar to‘yib ovqatlanmasligi ham ortdi. Indeks necha foizga oshdi va rivojlanish haqida qanday xulosa asosli?","options_en":["+10%; growth proves that everyone benefited","+50%; GDP growth alone does not establish broad welfare improvement","+8%; a higher poverty gap implies less poverty","−50%; child malnutrition is unrelated to welfare"],"options_ru":["+10%; рост доказывает пользу для каждого","+50%; роста ВВП недостаточно для доказательства всеобщего улучшения благосостояния","+8%; рост индекса означает уменьшение бедности","−50%; детское недоедание не связано с благосостоянием"],"options_uz":["+10%; o‘sish barchaga foyda berganini isbotlaydi","+50%; YaIM o‘sishi keng farovonlikni o‘zi isbotlamaydi","+8%; indeks oshishi kambag‘allik kamayganini bildiradi","−50%; bolalar ovqatlanishi farovonlikka aloqasiz"],"why":["The poverty-gap index rises by (0.30−0.20)/0.20=50%. GDP per person can grow even while deprivation worsens for vulnerable groups.","Индекс глубины бедности растёт на (0,30−0,20)/0,20=50%. Рост среднего ВВП не исключает ухудшения положения уязвимых групп.","Kambag‘allik tafovuti indeksi (0,30−0,20)/0,20=50% oshadi. O‘rtacha YaIM o‘sishi zaif guruhlar ahvolining yaxshilanishini kafolatlamaydi."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-057","d":"hard","sec":200,"k":"A","en":"The nominal exchange rate moves from 12,000 to 13,200 domestic units per foreign unit. Over the same period, the foreign price index rises 2% and the domestic price index rises 6%. Define the real exchange rate q=E×Pforeign/Pdomestic (a higher q is real depreciation). Approximately how much does q change, using exact index ratios?","ru":"Номинальный курс изменяется с 12 000 до 13 200 единиц местной валюты за иностранную. За тот же период зарубежный индекс цен растёт на 2%, внутренний на 6%. Определим реальный курс q=E×Pвнеш/Pвнутр (рост q означает реальное обесценение). Примерно на сколько меняется q по точным индексам?","uz":"Nominal kurs bir xorijiy birlik uchun 12 000 dan 13 200 mahalliy birlikka o‘zgaradi. Shu davrda xorijiy narx indeksi 2%, mahalliy indeksi 6% oshadi. Real kurs q=E×Pxorij/Pichki (q oshishi real qadrsizlanish). Aniq indekslar bo‘yicha q taxminan qancha o‘zgaradi?","options_en":["Rises about 5.85%, indicating real depreciation","Falls 10%, indicating real appreciation","Rises 18%, indicating real depreciation","Falls about 5.85%, indicating real appreciation"],"options_ru":["Растёт примерно на 5,85%; реальное обесценение","Падает на 10%; реальное укрепление","Растёт на 18%; реальное обесценение","Падает примерно на 5,85%; реальное укрепление"],"options_uz":["Taxminan 5,85% oshadi; real qadrsizlanish","10% tushadi; real qadrlanish","18% oshadi; real qadrsizlanish","Taxminan 5,85% tushadi; real qadrlanish"],"why":["The real exchange-rate factor is (13,200/12,000)×1.02/1.06≈1.0585. Thus q rises ≈5.85%, a real depreciation under the stated convention.","Коэффициент реального курса (13 200/12 000)×1,02/1,06≈1,0585. Реальное обесценение около 5,85% по принятому определению.","Real kurs koeffitsienti (13 200/12 000)×1,02/1,06≈1,0585. Berilgan ta’rifda real qadrsizlanish taxminan 5,85%."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-060","d":"hard","sec":180,"k":"C","en":"In a simple closed-economy Keynesian model, C=40+0.8Y, investment is 50 and government purchases are 30, all in $bn. There are no income taxes or imports, prices are fixed and capacity is sufficient. Potential output is $700bn. What increase in government purchases would close the initial output gap?","ru":"В простой закрытой кейнсианской модели C=40+0,8Y, инвестиции 50, госзакупки 30 (в млрд долларов). Нет налогов на доход и импорта, цены фиксированы, мощности достаточны. Потенциальный выпуск $700 млрд. На сколько следует увеличить госзакупки для устранения исходного разрыва выпуска?","uz":"Oddiy yopiq Keynes modelida C=40+0,8Y, investitsiya 50, davlat xaridi 30 (mlrd dollar). Daromad solig‘i va import yo‘q, narx o‘zgarmas, quvvat yetarli. Potensial ishlab chiqarish $700 mlrd. Dastlabki ishlab chiqarish tafovutini yopish uchun davlat xaridi qancha oshishi kerak?","options_en":["$100bn","$50bn","$20bn","$5bn"],"options_ru":["$100 млрд","$50 млрд","$20 млрд","$5 млрд"],"options_uz":["$100 mlrd","$50 mlrd","$20 mlrd","$5 mlrd"],"why":["Equilibrium Y=(40+50+30)/(1−0.8)=600. Gap to potential=100. Spending multiplier=1/(1−0.8)=5, so ΔG=100/5=$20bn.","Равновесие Y=(40+50+30)/(1−0,8)=600. Разрыв до потенциала 100; мультипликатор 5. Требуемые госзакупки 100/5=$20 млрд.","Muvozanat Y=(40+50+30)/(1−0,8)=600. Potensialgacha farq 100, multiplikator 5. ΔG=100/5=$20 mlrd."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-064","d":"hard","sec":180,"k":"B","en":"In year one, a firm''s wage per worker rises by 6% and output per worker rises by 2%. In year two, after inflation expectations become higher, wages rise by 9% and output per worker rises by 3%. Assume wages and productivity are measured from each previous year''s levels. What are the approximate changes in unit labour cost in years one and two?","ru":"В первом году зарплата на работника растёт на 6%, а выпуск на работника — на 2%. Во втором году, после повышения инфляционных ожиданий, зарплата растёт на 9%, производительность на 3%. Считайте каждый год относительно предыдущего. Каковы приблизительные темпы изменения затрат на труд на единицу выпуска в первом и втором годах?","uz":"Birinchi yili bir ishchining ish haqi 6%, ishchi boshiga mahsulot 2% oshadi. Ikkinchi yili inflyatsiya kutilmalari yuqorilagach ish haqi 9%, unumdorlik 3% oshadi. Har yillik o‘sish oldingi yilga nisbatan olinadi. Birlik mehnat xarajati birinchi va ikkinchi yilda taxminan necha foiz o‘zgaradi?","options_en":["Year 1 +8%; year 2 +12%","Year 1 +3.92%; year 2 +5.83%","Year 1 +4%; year 2 +6% exactly","Year 1 −3.92%; year 2 −5.83%"],"options_ru":["1-й год +8%; 2-й +12%","1-й год +3,92%; 2-й +5,83%","1-й год ровно +4%; 2-й ровно +6%","1-й год −3,92%; 2-й −5,83%"],"options_uz":["1-yil +8%; 2-yil +12%","1-yil +3,92%; 2-yil +5,83%","1-yil aynan +4%; 2-yil aynan +6%","1-yil −3,92%; 2-yil −5,83%"],"why":["Unit labour cost equals wage per worker divided by output per worker. The exact factors are 1.06/1.02≈1.0392 and 1.09/1.03≈1.0583, indicating stronger cost pressure in year two.","Единичные затраты на труд — зарплата на работника, делённая на его выпуск. Коэффициенты 1,06/1,02≈1,0392 и 1,09/1,03≈1,0583, то есть давление издержек усиливается.","Birlik mehnat xarajati ishchi ish haqining ishchi mahsulotiga nisbati. Koeffitsientlar 1,06/1,02≈1,0392 va 1,09/1,03≈1,0583; ikkinchi yilda xarajat bosimi kuchliroq."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-065","d":"hard","sec":200,"k":"B","en":"Initially aggregate demand is Qd=400−2P and short-run supply is Qs=100+P. Higher interest rates shift demand to Qd=370−2P, but an unrelated cost shock simultaneously shifts supply to Qs=70+P. Relative to the initial equilibrium, what happens to the price level and real output?","ru":"Первоначально совокупный спрос Qd=400−2P, краткосрочное предложение Qs=100+P. Повышение процентных ставок сдвигает спрос до Qd=370−2P, но независимый шок издержек одновременно сдвигает предложение до Qs=70+P. Как меняются уровень цен и реальный выпуск относительно первоначального равновесия?","uz":"Dastlab yalpi talab Qd=400−2P, qisqa muddatli taklif Qs=100+P. Foiz stavkasi oshishi talabni Qd=370−2P ga kamaytiradi, mustaqil xarajat shoki taklifni Qs=70+P ga siljitadi. Avvalgi muvozanatga nisbatan narx darajasi va real ishlab chiqarish qanday o‘zgaradi?","options_en":["Price falls 10; output stays at 200","Price remains 100; output falls from 200 to 170","Price rises 10; output rises from 200 to 220","Price falls 20; output falls from 200 to 170"],"options_ru":["Цены падают на 10; выпуск остаётся 200","Цены остаются 100; выпуск падает с 200 до 170","Цены растут на 10; выпуск растёт с 200 до 220","Цены падают на 20; выпуск падает с 200 до 170"],"options_uz":["Narx 10 ga tushadi; ishlab chiqarish 200 qoladi","Narx 100 bo‘lib qoladi; ishlab chiqarish 200 dan 170 ga kamayadi","Narx 10 ga oshadi; ishlab chiqarish 200 dan 220 ga oshadi","Narx 20 ga kamayadi; ishlab chiqarish 200 dan 170 ga tushadi"],"why":["Initially 400−2P=100+P gives P=100,Q=200. Afterwards 370−2P=70+P still gives P=100 but Q=170. The cost shock offsets disinflation from demand tightening while output falls.","Изначально P=100, Q=200. После двух сдвигов P=100, Q=170. Шок издержек компенсирует сдерживание цен спросом, но выпуск падает.","Dastlab P=100,Q=200. Ikkala siljishdan keyin P=100,Q=170. Xarajat shoki talabni cheklashning narxga ta’sirini qoplaydi, ishlab chiqarish pasayadi."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-067","d":"hard","sec":190,"k":"C","en":"A central bank purchases $500m in government bonds directly from banks and credits the banks with additional reserves. In a deliberately simplified model, the reserve requirement is 20%, all loans are redeposited, and banks keep no excess reserves. What is the MAXIMUM total increase in bank deposits supported by these new reserves, and what is the corresponding maximum additional bank lending?","ru":"Центральный банк покупает у банков государственные облигации на $500 млн и зачисляет им новые резервы. В предельно упрощённой модели обязательная норма резервов 20%, все кредиты возвращаются в систему как депозиты, избыточных резервов нет. Каковы максимальный суммарный прирост депозитов и соответствующий максимальный объём дополнительных кредитов?","uz":"Markaziy bank banklardan $500 mln davlat obligatsiyasini sotib olib, ularga yangi zaxira yozadi. Juda soddalashtirilgan modelda majburiy zaxira normasi 20%, barcha kreditlar yana depozit bo‘lib qaytadi, ortiqcha zaxira yo‘q. Depozitlarning maksimal jami qo‘shimcha o‘sishi va mos qo‘shimcha kredit miqdori qancha?","options_en":["Deposits $500m; loans $500m","Deposits $2.0bn; loans $2.5bn","Deposits $2.5bn; loans $2.0bn","Deposits $2.5bn; loans $2.5bn"],"options_ru":["Депозиты $500 млн; кредиты $500 млн","Депозиты $2,0 млрд; кредиты $2,5 млрд","Депозиты $2,5 млрд; кредиты $2,0 млрд","Депозиты $2,5 млрд; кредиты $2,5 млрд"],"options_uz":["Depozitlar $500 mln; kredit $500 mln","Depozitlar $2,0 mlrd; kredit $2,5 mlrd","Depozitlar $2,5 mlrd; kredit $2,0 mlrd","Depozitlar $2,5 mlrd; kredit $2,5 mlrd"],"why":["The deposit multiplier is 1/0.2=5, so additional total deposits can reach 5×$500m=$2.5bn. Required reserves use $500m, leaving up to $2.0bn additional loans in the idealised model.","Депозитный мультипликатор 1/0,2=5, максимальные новые депозиты $2,5 млрд. Под обязательные резервы идут $500 млн, на кредиты — до $2 млрд.","Depozit multiplikatori 1/0,2=5, qo‘shimcha depozit $2,5 mlrd. Majburiy zaxira $500 mln, kredit uchun maksimal $2,0 mlrd."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-068","d":"hard","sec":180,"k":"A","en":"A country''s real recorded output rises by $100m during a year of deforestation. A consistent monetary valuation estimates that depletion of natural capital reduces the national asset base by $130m, with no other changes. In a simplified sustainability-adjusted net-output measure that deducts this depletion, what is the net change and the policy concern?","ru":"В стране реальный учтённый выпуск за год увеличивается на $100 млн благодаря вырубке лесов. Сопоставимая денежная оценка показывает истощение природного капитала на $130 млн, прочих изменений нет. Каково чистое изменение условного показателя выпуска с вычетом этого истощения и какой риск он иллюстрирует?","uz":"Mamlakatda o‘rmonni kesish hisobiga yillik real qayd etilgan mahsulot $100 mln oshadi. Taqqoslanadigan pul bahosida tabiiy kapitalning kamayishi $130 mln, boshqa o‘zgarish yo‘q. Shu yo‘qotishni ayiradigan soddalashtirilgan barqarorlikka mos sof mahsulot o‘zgarishi qancha va qanday xavfni ko‘rsatadi?","options_en":["−$30m; GDP growth can coexist with depletion of underlying productive assets","+ $230m; all resource depletion is income","−$130m; recorded GDP must have fallen","+$100m; natural-capital loss is irrelevant"],"options_ru":["−$30 млн; рост ВВП может сопровождаться истощением производственных активов","+$230 млн; истощение — всегда дополнительный доход","−$130 млн; учтённый ВВП обязан упасть","+$100 млн; потеря природного капитала не имеет значения"],"options_uz":["−$30 mln; YaIM o‘sishi tabiiy ishlab chiqarish aktivlarini kamaytirishi mumkin","+$230 mln; resurs tugashi doim qo‘shimcha daromad","−$130 mln; qayd etilgan YaIM albatta tushgan","+$100 mln; tabiiy kapital yo‘qotish ahamiyatsiz"],"why":["Recorded output rises $100m but valued natural-capital depletion is $130m, leaving $100m−$130m=−$30m in this adjusted measure. Short-run GDP growth need not be sustainable.","Учтённый выпуск +$100 млн, истощение природного капитала −$130 млн. Скорректированный показатель −$30 млн: рост ВВП не всегда устойчив.","Qayd etilgan mahsulot +$100 mln, tabiiy kapital kamayishi −$130 mln. Tuzatilgan ko‘rsatkich −$30 mln, YaIM o‘sishi doim barqaror emas."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-049","d":"medium","sec":165,"k":"A","en":"A commercial bank pays 3% annual interest on $80m of deposits and earns 8% annual interest on $60m of loans. Ignore bad debts, fees, reserve interest and other expenses. What is its annual gross interest margin in dollars, and which role of a bank does it illustrate?","ru":"Коммерческий банк платит 3% годовых по депозитам $80 млн и получает 8% годовых по кредитам $60 млн. Игнорируйте дефолты, комиссии, процент по резервам и другие затраты. Чему равна годовая валовая процентная маржа в долларах и какую функцию банка это иллюстрирует?","uz":"Tijorat banki $80 mln depozitga yillik 3% foiz to‘laydi, $60 mln kreditdan yillik 8% oladi. Defolt, komissiya, zaxira foizi va boshqa xarajatni hisoblamang. Yillik yalpi foiz marjasi dollarda qancha va bankning qanday vazifasini ko‘rsatadi?","options_en":["$2.4m; financial intermediation between savers and borrowers","$4.8m; issuing domestic currency","$7.2m; collecting income taxes","$2.4m; eliminating all credit risk"],"options_ru":["$2,4 млн; финансовое посредничество между вкладчиками и заёмщиками","$4,8 млн; выпуск национальной валюты","$7,2 млн; сбор подоходного налога","$2,4 млн; полное устранение кредитного риска"],"options_uz":["$2,4 mln; jamg‘aruvchi va qarz oluvchi o‘rtasidagi vositachilik","$4,8 mln; milliy valuta chiqarish","$7,2 mln; daromad solig‘i yig‘ish","$2,4 mln; barcha kredit xavfini yo‘qotish"],"why":["Loan interest is 0.08×$60m=$4.8m; deposit interest 0.03×$80m=$2.4m; spread in dollars=$2.4m. This illustrates financial intermediation, not risk elimination.","Проценты по кредитам 0,08×$60 млн=$4,8 млн, по депозитам 0,03×$80 млн=$2,4 млн; разница $2,4 млн. Это финансовое посредничество.","Kredit foizi 0,08×$60 mln=$4,8 mln, depozit foizi 0,03×$80 mln=$2,4 mln; farq $2,4 mln. Bu moliyaviy vositachilikdir."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-051","d":"medium","sec":155,"k":"B","en":"A displaced textile worker has qualifications that no longer match local vacancies. After accredited nursing training, she becomes eligible for hospital jobs, while aggregate spending is unchanged. Which paired economic effects are most plausible?","ru":"Уволенный текстильщик не обладает квалификацией для открытых местных вакансий. После аккредитованного обучения сестринскому делу он получает право претендовать на работу в больнице; совокупные расходы не меняются. Какая пара экономических эффектов наиболее вероятна?","uz":"Ishdan bo‘shatilgan to‘qimachilik ishchisining malakasi mahalliy vakansiyalarga mos emas. Akkreditatsiyalangan hamshiralik kursidan keyin u shifoxona ishlariga mos bo‘ladi, yalpi xarajatlar o‘zgarmaydi. Qaysi ikki iqtisodiy ta’sir ehtimolli?","options_en":["Cyclical unemployment rises and human capital necessarily falls","Structural unemployment may fall as human capital becomes more relevant to vacancies","Frictional unemployment disappears permanently for all workers","The central bank must raise the money supply to validate the training"],"options_ru":["Циклическая безработица растёт, человеческий капитал обязательно падает","Структурная безработица может снизиться благодаря навыкам, соответствующим вакансиям","Фрикционная безработица навсегда исчезает у всех работников","Центральный банк обязан увеличить денежную массу для обучения"],"options_uz":["Davriy ishsizlik oshib, inson kapitali albatta kamayadi","Vakansiyaga mos malaka oshgani uchun tarkibiy ishsizlik kamayishi mumkin","Barcha ishchilarda friksion ishsizlik abadiy yo‘qoladi","Markaziy bank o‘qitish uchun pul massasini oshirishi shart"],"why":["Training changes the supply of relevant skills and reduces the mismatch between workers and vacancies, potentially lowering structural unemployment without an AD boost.","Обучение повышает пригодность навыков для вакансий и может уменьшать структурную безработицу без стимулирования AD.","Ta’lim ko‘nikmani bo‘sh ishga moslashtirib, yalpi talab oshmasdan ham tarkibiy ishsizlikni kamaytirishi mumkin."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-054","d":"medium","sec":155,"k":"D","en":"Labour demand is Ld=1500−30w and labour supply is Ls=600+20w, where w is hourly wage. The government sets an enforceable minimum wage of $20. Compared with the market-clearing wage, what are employment and excess labour supply at the minimum wage?","ru":"Спрос на труд Ld=1500−30w, предложение Ls=600+20w, где w — почасовая зарплата. Государство вводит обязательный минимум $20. Каковы занятость и избыточное предложение труда при этой ставке по сравнению с рыночным равновесием?","uz":"Mehnat talabi Ld=1500−30w, taklif Ls=600+20w, bunda w soatlik ish haqi. Davlat majburiy eng kam ish haqini $20 belgilaydi. Muvozanatga nisbatan shu ish haqida bandlik va ortiqcha mehnat taklifi qancha?","options_en":["Employment 1,000; excess supply zero","Employment 960; excess supply 40","Employment 900; excess supply zero","Employment 900; excess supply 100"],"options_ru":["Занятость 1 000; избыточного предложения нет","Занятость 960; излишек 40","Занятость 900; избыточного предложения нет","Занятость 900; излишек 100"],"options_uz":["Bandlik 1000; ortiqcha taklif nol","Bandlik 960; ortiqcha taklif 40","Bandlik 900; ortiqcha taklif nol","Bandlik 900; ortiqcha taklif 100"],"why":["Market clearing gives 1500−30w=600+20w, w=18, L=960. At w=20, demand=900, supply=1000, so actual employment is 900 and excess supply 100.","Рынок: w=18, L=960. При минимуме w=20 спрос на труд 900, предложение 1 000; занято 900, излишек труда 100.","Muvozanatda w=18, L=960. w=20 da talab 900, taklif 1000; bandlik 900, ortiqcha taklif 100."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-058","d":"medium","sec":150,"k":"C","en":"Eighty unemployed skilled workers live in a region with no suitable vacancies; another region has 100 matching vacancies. Each worker would gain $500 monthly income but face an extra $600 monthly housing and commuting cost if moving. A relocation grant offsets $200 of those costs monthly. Assume other conditions are unchanged. What is the net monthly incentive to move per worker?","ru":"В одном регионе 80 квалифицированных безработных и нет подходящих вакансий; в другом есть 100 соответствующих вакансий. Каждый после переезда получит дополнительно $500 в месяц, но расходы на жильё и дорогу увеличатся на $600. Субсидия на переезд компенсирует $200 этих расходов ежемесячно. При прочих равных каков чистый месячный стимул переехать для одного работника?","uz":"Bir hududda mos ish yo‘q, 80 nafar malakali ishsiz bor; boshqa hududda 100 mos vakansiya bor. Har ishchi ko‘chganda oyiga $500 ko‘proq topadi, lekin uy-joy va qatnov xarajati $600 oshadi. Ko‘chish granti oyiga $200 ni qoplaydi. Boshqa shartlar o‘zgarmasa, har ishchi uchun sof oylik rag‘bat qancha?","options_en":["−$100; relocation is still financially unattractive","+$500; mobility costs do not matter","+$100; support can make relocation financially attractive","+ $700; every vacant job must be filled"],"options_ru":["−$100; переезд по-прежнему невыгоден","+$500; затраты мобильности не имеют значения","+$100; поддержка может сделать переезд выгодным","+$700; все вакансии обязательно заполнятся"],"options_uz":["−$100; ko‘chish hali foydasiz","+$500; ko‘chish xarajati ahamiyatsiz","+$100; yordam ko‘chishni moliyaviy jozibador qilishi mumkin","+$700; barcha vakansiyalar albatta to‘ladi"],"why":["Incremental monthly net benefit = higher pay $500 − higher expenses $600 + grant $200 = +$100. Mobility support can overcome a cost barrier, although not all workers must move.","Чистый месячный результат $500−$600+$200=+$100. Поддержка может устранить финансовый барьер, но не гарантирует переезд каждого.","Sof oylik natija $500−$600+$200=+$100. Yordam xarajat to‘sig‘ini yengishi mumkin, ammo barcha ishchi ko‘chishi shart emas."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-061","d":"medium","sec":150,"k":"A","en":"A government compares two equally costly policies: one funds technical training and reliable transport links; the other provides a one-month rebate on household spending. Holding other factors constant, which distinction is most defensible?","ru":"Государство сравнивает две равные по стоимости меры: финансирование технической подготовки и надёжного транспорта либо разовую месячную скидку на покупки домохозяйств. При прочих равных какое различие наиболее обоснованно?","uz":"Davlat bir xil xarajatli ikki siyosatni solishtiradi: texnik malaka va ishonchli transportni moliyalashtirish yoki oilalarning bir oylik xaridiga chegirma berish. Boshqa sharoit o‘zgarmasa, qaysi farq eng asosli?","options_en":["Training and infrastructure can increase productive capacity over time; the rebate more directly boosts short-run spending","Both measures must shift long-run supply right by exactly the same amount","The rebate necessarily increases available skilled labour permanently","Infrastructure always reduces real output because its initial costs are positive"],"options_ru":["Подготовка и инфраструктура способны увеличить производственный потенциал; скидка прежде всего стимулирует краткосрочные расходы","Обе меры обязательно одинаково сдвигают долгосрочное предложение","Скидка навсегда повышает квалификацию рабочей силы","Инфраструктура всегда снижает выпуск из-за первоначальных затрат"],"options_uz":["Malaka va infratuzilma vaqt o‘tib salohiyatni oshirishi mumkin, chegirma esa ko‘proq qisqa muddatli xarajatni rag‘batlantiradi","Ikkalasi uzoq muddatli taklifni aynan teng siljitadi","Chegirma ishchilar malakasini doimiy oshiradi","Boshlang‘ich xarajati borligi uchun infratuzilma doim mahsulotni kamaytiradi"],"why":["Skills and productive infrastructure primarily change supply capacity over time; a temporary consumer rebate operates mainly through short-term aggregate spending.","Навыки и инфраструктура могут повысить долгосрочный потенциал; временная скидка действует прежде всего через текущие расходы и AD.","Ko‘nikma va infratuzilma uzoq muddatli salohiyatni o‘zgartirishi mumkin; vaqtinchalik chegirma joriy ADga ta’sir qiladi."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-066","d":"medium","sec":160,"k":"B","en":"The labour force remains 1,250 people. Before an effective skills programme, 1,000 are employed; after, 1,100 are employed, with all new jobs going to previously unemployed members of the same labour force. What happens to the measured unemployment rate?","ru":"Численность рабочей силы остаётся 1 250 человек. До эффективной программы переподготовки заняты 1 000, после неё — 1 100; все новые рабочие места получают ранее безработные из той же рабочей силы. Как изменяется измеряемый уровень безработицы?","uz":"Ishchi kuchi 1250 kishi bo‘lib qoladi. Samarali malaka dasturigacha 1000 kishi ishlaydi, keyin 1100; yangi ishlarning barchasi shu ishchi kuchidagi avvalgi ishsizlarga tegadi. O‘lchanadigan ishsizlik darajasi qanday o‘zgaradi?","options_en":["From 20% to 20%","From 20% to 12%","From 12% to 20%","From 20% to 8%"],"options_ru":["С 20% до 20%","С 20% до 12%","С 12% до 20%","С 20% до 8%"],"options_uz":["20% dan 20% ga","20% dan 12% ga","12% dan 20% ga","20% dan 8% ga"],"why":["Unemployed initially 1250−1000=250 (20%). Afterwards 1250−1100=150 (12%), a fall of eight percentage points.","Сначала безработных 250/1250=20%, после — 150/1250=12%. Снижение на 8 процентных пунктов.","Dastlab ishsizlar 250/1250=20%, keyin 150/1250=12%. Pasayish 8 foiz punkt."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-069","d":"medium","sec":165,"k":"D","en":"A government expected 2,000 applicants for a subsidy of $50 each and set an initial budget of $100,000. Actual eligible take-up reaches 6,000 applicants with no change to the grant amount. By how much is the programme over budget, and what public-finance risk is illustrated?","ru":"Государство ожидало 2 000 заявителей на субсидию по $50 каждому и выделило $100 000. Фактически право на выплату получили 6 000 заявителей при неизменном размере субсидии. На сколько программа превышает бюджет и какой риск государственных финансов иллюстрирует?","uz":"Davlat har biriga $50 subsidiyaga 2000 ariza kutilib, $100 000 budjet ajratgan. Amalda subsidiya olish huquqiga ega 6000 arizachi bo‘ldi, miqdor o‘zgarmadi. Budjet qancha oshib ketadi va davlat moliyasida qanday xavfni ko‘rsatadi?","options_en":["$100,000; all forecasts were exact","$200,000; take-up uncertainty can crowd out other public services","$300,000; an overspend can never affect other programmes","$400,000; government debt must automatically vanish"],"options_ru":["$100 000; прогноз был точным","$200 000; неопределённость участия способна вытеснить другие бюджетные услуги","$300 000; перерасход не влияет на другие программы","$400 000; госдолг автоматически исчезает"],"options_uz":["$100 000; prognoz aniq edi","$200 000; talab noaniqligi boshqa davlat xizmatlarini siqib chiqarishi mumkin","$300 000; ortiqcha xarajat boshqa dasturga ta’sir qilmaydi","$400 000; davlat qarzi o‘z-o‘zidan yo‘qoladi"],"why":["Actual subsidy spending 6,000×$50=$300,000 compared with $100,000 planned, an overspend of $200,000. Under a constrained budget, funding gaps may displace higher-priority services.","Фактические расходы 6 000×$50=$300 000 вместо $100 000: перерасход $200 000. При ограниченном бюджете могут пострадать другие услуги.","Amaldagi xarajat 6000×$50=$300 000, reja $100 000; ortiqcha $200 000. Cheklangan budjetda boshqa xizmatlar siqilishi mumkin."]},{"ref":"EC9708:G2:EC9708-G2-T6-P-070","d":"medium","sec":155,"k":"C","en":"A household holds an instantly accessible $3,000 cash buffer for unforeseen emergency bills instead of an insured savings account paying 4% interest annually. Assume no fees, tax or other effects. What is the annual interest opportunity cost of its liquidity choice and the motive for money holding?","ru":"Семья держит доступный в любой момент запас наличных $3 000 на непредвиденные расходы вместо застрахованного сберегательного счёта с доходностью 4% годовых. Комиссий, налогов и других эффектов нет. Какова годовая альтернативная стоимость ликвидности в виде потерянных процентов и каков мотив хранения денег?","uz":"Oila kutilmagan xarajat uchun darhol ishlatish mumkin bo‘lgan $3000 naqd zaxira saqlaydi, yiliga 4% beradigan sug‘urtalangan omonatga qo‘ymaydi. Komissiya, soliq va boshqa ta’sir yo‘q. Likvidlik tanlovining yillik yo‘qotilgan foiz qiymati va pul saqlash sababi qanday?","options_en":["$12; speculative motive","$3,000; transactions motive only","$120; precautionary motive","$120; proof that cash is an investment asset yielding 4%"],"options_ru":["$12; спекулятивный мотив","$3 000; только трансакционный мотив","$120; мотив предосторожности","$120; доказательство доходности наличных 4%"],"options_uz":["$12; spekulyativ sabab","$3000; faqat tranzaksiya sababi","$120; ehtiyotkorlik sababi","$120; naqd pul 4% daromadli aktiv ekanining isboti"],"why":["Forgone interest=$3,000×0.04=$120 annually. The cash is held for unpredictable emergencies, a precautionary demand for money despite its opportunity cost.","Упущенные проценты $3 000×0,04=$120 в год. Наличные держат на непредвиденные расходы — мотив предосторожности.","Yo‘qotilgan foiz $3000×0,04=$120/yil. Pul kutilmagan ehtiyoj uchun saqlanmoqda — ehtiyotkorlik motivi."]}]'::jsonb;
 x jsonb; o record; new_id bigint; i int; ix int; k text; b text; cnt int; e int; m int; h int; why_ru text; why_uz text; why_en text;
BEGIN
 IF jsonb_array_length(d)<>28 THEN RAISE EXCEPTION 'expected_28'; END IF;
 SELECT count(*) INTO cnt FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id WHERE p.subject_id=7 AND p.tour_no=6 AND l.is_active;
 IF cnt<>70 THEN RAISE EXCEPTION 'pool_precondition: %',cnt; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(d) LOOP
   b:=x->>'ref';k:=x->>'k';ix:=ascii(k)-65;
   IF k NOT IN ('A','B','C','D') OR x->>'d' NOT IN ('medium','hard') OR jsonb_array_length(x->'options_en')<>4 OR jsonb_array_length(x->'options_ru')<>4 OR jsonb_array_length(x->'options_uz')<>4 THEN RAISE EXCEPTION 'invalid_question: %',b; END IF;
   SELECT q.*, l.pool_id,l.order_no INTO STRICT o FROM public.questions q
      JOIN public.practice_pool_questions l ON l.question_id=q.id AND l.is_active
      JOIN public.practice_pools p ON p.id=l.pool_id AND p.tour_no=6
      WHERE q.subject_id=7 AND p.subject_id=7 AND q.book_ref=b;
   IF EXISTS(SELECT 1 FROM public.practice_answers a WHERE a.question_id=o.id) OR EXISTS(SELECT 1 FROM public.questions q WHERE q.subject_id=7 AND q.book_ref=b||'-V2') THEN RAISE EXCEPTION 'history_or_version_conflict: %',b; END IF;
   why_ru:=x->'why'->>1;why_uz:=x->'why'->>2;why_en:=x->'why'->>0;
   INSERT INTO public.questions(subject_id,topic,subtopic,difficulty,qtype,question_text,options_text,correct_answer,explanation,image_url,is_active,question_text_ru,question_text_uz,question_text_en,options_text_ru,options_text_uz,options_text_en,explanation_ru,explanation_uz,explanation_en,book_ref,time_limit_sec,quality_flag,quality_status)
   VALUES(o.subject_id,o.topic,o.subtopic,x->>'d','mcq',x->>'en',(x->'options_en')::text,k,
       'Correct: '||(x->'options_en'->>ix)||E'\n'||why_en,NULL,true,
       x->>'ru',x->>'uz',x->>'en',(x->'options_ru')::text,(x->'options_uz')::text,(x->'options_en')::text,
       'Ответ: '||(x->'options_ru'->>ix)||E'\n'||why_ru,
       'Javob: '||(x->'options_uz'->>ix)||E'\n'||why_uz,
       'Correct: '||(x->'options_en'->>ix)||E'\n'||why_en,b||'-V2',(x->>'sec')::int,o.quality_flag,'published')
   RETURNING id INTO new_id;
   UPDATE public.practice_pool_questions SET is_active=false WHERE pool_id=o.pool_id AND question_id=o.id AND is_active;
   GET DIAGNOSTICS cnt=ROW_COUNT;
   IF cnt<>1 THEN RAISE EXCEPTION 'link_count: %',b; END IF;
   INSERT INTO public.practice_pool_questions(pool_id,question_id,order_no,is_active) VALUES(o.pool_id,new_id,o.order_no,true);
   INSERT INTO public.question_version_links(old_question_id,new_question_id,link_type,reason) VALUES(o.id,new_id,'replacement','Economics T6 difficulty content replacement; historical question retained');
   FOR i IN 0..3 LOOP
     INSERT INTO public.question_answer_diagnostics(question_id,answer_kind,answer_key,answer_value,is_correct,mistake_type,weak_skill,feedback_ru,feedback_uz,feedback_en,next_action_ru,next_action_uz,next_action_en,rule_json,quality_status)
     VALUES(new_id,'mcq_option',chr(65+i),NULL,i=ix,CASE WHEN i=ix THEN NULL ELSE 'multi_step_economic_reasoning' END,o.subtopic,
       'Выбрано: '||(x->'options_ru'->>i)||E'\n'||why_ru||E'\nОтвет: '||(x->'options_ru'->>ix),
       'Tanlov: '||(x->'options_uz'->>i)||E'\n'||why_uz||E'\nJavob: '||(x->'options_uz'->>ix),
       'Selected: '||(x->'options_en'->>i)||E'\n'||why_en||E'\nCorrect: '||(x->'options_en'->>ix),
       CASE WHEN i=ix THEN NULL ELSE 'Проверьте способ решения.' END,CASE WHEN i=ix THEN NULL ELSE 'Yechimni qayta tekshiring.' END,CASE WHEN i=ix THEN NULL ELSE 'Review the method.' END,
       jsonb_build_object('diagnostic_code','EC9708_G2_T6P'||substring(b from 'P-([0-9]{3})')||'_V2_'||chr(65+i)),'published');
   END LOOP;
 END LOOP;
 UPDATE public.questions q SET difficulty=CASE WHEN right(q.book_ref,3) IN ('001','002','003','004','009','012','013','014','015','020','024','025','028','032','033','036','040','043','045','050','059','063') THEN 'medium' ELSE 'easy' END
 WHERE q.subject_id=7 AND q.book_ref ~ '^EC9708:G2:EC9708-G2-T6-P-[0-9]{3}$'
 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(d) z WHERE z->>'ref'=q.book_ref);
 GET DIAGNOSTICS cnt=ROW_COUNT;
 IF cnt<>42 THEN RAISE EXCEPTION 'unchanged_count: %',cnt; END IF;
 SELECT count(*),count(*) FILTER(WHERE q.difficulty='easy'),count(*) FILTER(WHERE q.difficulty='medium'),count(*) FILTER(WHERE q.difficulty='hard')
 INTO cnt,e,m,h FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id JOIN public.questions q ON q.id=l.question_id
 WHERE p.subject_id=7 AND p.tour_no=6 AND l.is_active;
 IF cnt<>70 OR e<>20 OR m<>30 OR h<>20 THEN RAISE EXCEPTION 'postcondition_fail: %,%,%,%',cnt,e,m,h; END IF;
END $t$;
COMMIT;
